-- [npcID] = its voice line, in the languages the game has it in (a language without it: no line shown)
ns.CinematicLines = {
	[639] = { enUS = "None may challenge the Brotherhood!", deDE = "Niemand darf die Bruderschaft herausfordern!", esES = "¡Nadie puede desafiar a la Hermandad!", esMX = "¡Nadie puede enfrentarse a la Hermandad!", frFR = "Nul ne peut défier la Confrérie !", ptBR = "Ninguém pode desafiar a Irmandade!", ruRU = "Никто не смеет бросать вызов братству!" },
	[646] = { enUS = "D'ah! Now you're making me angry! ", deDE = "D'ah! Jetzt macht Ihr mich wütend!", esES = "¡Bah! ¡Me estás haciendo enfadar!", esMX = "¡Ah! ¡Me están haciendo enojar!", frFR = "Je commence sérieusement à m'échauffer !", ptBR = "Argh! Você está me irritando! ", ruRU = "Тьфу! Теперь ты меня злишь!" },
	[1842] = { enUS = "Remove your disguise, lest you feel the bite of my blade when the fury has taken control.", deDE = "Entfernt Eure Verkleidung, sonst bekommt Ihr den Biss meiner Klinge zu spüren, sobald der Zorn sich meiner bemächtigt hat.", esES = "Quítate el disfraz, no vaya a ser que sientas el mordisco de mi espada cuando la furia se haga con el control.", esMX = "Quítate el disfraz, no vaya a ser que sientas el mordisco de mi espada cuando la furia se haga con el control.", frFR = "Enlevez votre déguisement, à moins que vous ne vouliez tâter de ma lame quand je serai bien énervé.", ptBR = "Retire o disfarce se não quiser sentir o toque da minha lâmina quando a fúria tomar controle.", ruRU = "Сними свою маску, иначе ты не почувствуешь укус моего меча, когда меня охватит ярость." },
	[1853] = { enUS = "School is in session!", deDE = "Der Unterricht hat begonnen!", esES = "¡Estamos dando clase!", esMX = "¡Estamos dando clase!", frFR = "Les cours ont commencé !", ptBR = "De volta às aulas!", ruRU = "Занятия начались!" },
	[2748] = { enUS = "Who dares awaken Archaedas? Who dares the wrath of the Makers?", deDE = "Wer wagt es, Archaedas zu wecken? Wer riskiert den Zorn der Schöpfer?", esES = "¿Quién osa despertar a Archaedas? ¿Quién se atreve a despertar la ira de los Hacedores?", esMX = "¿Quién osa despertar a Archaedas? ¿Quién provoca la ira de los Creadores?", frFR = "Qui ose éveiller Archaedas ? Qui défie la colère des Faiseurs ?", ptBR = "Quem ousa acordar Arkhaedas? Quem desafia a ira dos Criadores?", ruRU = "Кто смеет будить Аркедаса? Кто не боится гнева Мастеров?" },
	[3975] = { enUS = "Blades of light!", deDE = "Klingen des Lichts!", esES = "¡Espadas de luz!", esMX = "¡Espadas de luz!", frFR = "Lames de lumière !", ptBR = "Espadas da luz!", ruRU = "Клинки света!" },
	[3976] = { enUS = "Infidels! They must be purified!", deDE = "Ungläubige! Sie müssen geläutert werden!", esES = "¡Infieles! ¡Hay que purificarlos!", esMX = "¡Infieles! ¡Hay que purificarlos!", frFR = "Des infidèles ! Ils doivent être purifiés !", ptBR = "Infiéis! Eles precisam ser purificados!", ruRU = "Неверные! Очистим их от скверны!" },
	[3977] = { enUS = "The Light has spoken!" },
	[4275] = { enUS = "You, too, shall serve!", deDE = "Auch Ihr sollt dienen!", esES = "¡Tú también servirás!", esMX = "¡Tú también serás mi esclavo!", frFR = "Vous me servirez aussi !", ptBR = "Você também vai servir!", ruRU = "И ты будешь служить!" },
	[4421] = { enUS = "Troublesome whelps. I'll teach you to interfere!" },
	[4832] = { enUS = "Who dares disturb my meditation?", deDE = "Wer stört da meine Meditation?", esES = "¿Quién osa perturbar mi meditación?", esMX = "¿Quién osa interrumpir mi meditación?", frFR = "Qui ose interrompre ma méditation ?", ptBR = "Quem ousa perturbar minha meditação?", ruRU = "Кто смеет прерывать мои размышления?" },
	[5709] = { enUS = "Defeated my minions? Then face me, mortals!", deDE = "Ihr habt meine Wächter besiegt? Nun werdet Ihr gegen mich bestehen müssen, Sterbliche!", esES = "¿Derrotasteis a mis esbirros? ¡Pues ahora enfrentaos a mí, mortales!", esMX = "¿Derrotaron a mis esbirros? ¡Pues ahora enfréntense a mí, mortales!", frFR = "Vous avez vaincu mes serviteurs ? Alors affrontez-moi, mortels !", ptBR = "Derrotaram os meus lacaios? Então venham me enfrentar, mortais!", ruRU = "Одолели моих приспешников? Тогда сразитесь со мной, смертные!" },
	[6109] = { enUS = "Come, little ones. Face me!", deDE = "Kommt, ihr Wichte! Tretet mir gegenüber!", esES = "Vamos, pequeñajos. ¡Luchad conmigo!", esMX = "Vamos, pequeñajos. ¡Luchen conmigo!", frFR = "Venez m'affronter, mes petits !", ptBR = "Venham, pequeninos. Enfrentem-me!", ruRU = "Сюда, малыши. Сразитесь со мной!" },
	[7228] = { enUS = "None may steal the secrets of the Makers!" },
	[7267] = { enUS = "This desert be mine!", deDE = "Diese Wüste ist mein!", esES = "¡Este desierto es mío!", esMX = "¡El desierto es mío!", frFR = "Ce désert sera mien !", ptBR = "Este deserto é meu!", ruRU = "Пустыня станет моей!" },
	[7358] = { enUS = "You'll never leave this place alive.", deDE = "Ihr kommt hier niemals lebend raus.", esES = "Nunca dejarás con vida este lugar.", esMX = "Nunca saldrán de aquí… vivos…", frFR = "Vous ne sortirez jamais d'ici vivants.", ptBR = "Vocês nunca sairão vivos daqui.", ruRU = "Ты не уйдешь отсюда $gживым:живой;." },
	[7800] = { enUS = "Usurpers! Gnomeregan is mine!", deDE = "Thronräuber! Gnomeregan ist mein!", esES = "¡Usurpadores! ¡Gnomeregan es mío!", esMX = "¡Usurpadores! ¡Gnomeregan es mía!", frFR = "Usurpateurs ! Gnomeregan est à moi !", ptBR = "Usurpadores! Gnomeregan é minha!", ruRU = "Узурпаторы! Гномреган мой!" },
	[8443] = { enUS = "DIE, MORTALS!", deDE = "STERBT, STERBLICHE WESEN!", esES = "¡MORID, MORTALES!", esMX = "¡MUERAN, MORTALES!", frFR = "MOUREZ, MORTELS !", ptBR = "MORRAM, MORTAIS!", ruRU = "УМРИТЕ, СМЕРТНЫЕ!" },
	[9019] = { enUS = "Hail to the king, baby!", deDE = "Grüße dem König, Baby!", esES = "¡Viva el rey, nena!", esMX = "¡Viva el rey, nena!", frFR = "Salut au roi, bébé !", ptBR = "Salve o rei, nenê!", ruRU = "Слава королю, крошка!" },
	[10184] = { enUS = "%s takes in a deep breath...", deDE = "%s atmet tief ein...", esES = "respira profundamente...", esMX = "%s toma aliento...", frFR = "%s prend une grande inspiration…", ptBR = "%s respira fundo...", ruRU = "%s делает глубокий вдох…" },
	[10429] = { enUS = "Defilers!", deDE = "Entweiher!", esES = "¡Rapiñadores!", esMX = "¡Rapiñadores!", frFR = "Profanateurs !", ptBR = "Profanadores!", ruRU = "Осквернители!" },
	[10440] = { enUS = "Time to take matters into my own hands. Come. Enter my domain and challenge the might of the Scourge!", deDE = "Es ist an der Zeit, die Dinge selbst in die Hand zu nehmen. Kommt nur. Betretet mein Reich und fordert die Macht der Geißel heraus!", esES = "Ya es hora de tomar el asunto en mis propias manos. Ven. ¡Entra en mis dominios y desafía el poder de la Plaga!", esMX = "Ya es hora de tomar el asunto en mis propias manos. Ven. ¡Entra en mis dominios y desafía el poder de la Plaga!", frFR = "Il est temps que je prenne les choses en mains. Venez. Entrez dans mon domaine. Défiez la puissance du Fléau !", ptBR = "É hora de eu mesmo cuidar disso. Venha, entre em meus domínios e desafie o poder do Flagelo!", ruRU = "Пора взять дело в свои руки. Идем. Вступи в мои владения и брось вызов могуществу Плети!" },
	[11382] = { enUS = "I'll feed your souls to Hakkar himself!", deDE = "Ich werde Hakkar eure Seelen zum Fraß vorwerfen!", esES = "¡Serviré en bandeja vuestras almas al mismísimo Hakkar!", esMX = "¡Hakkar devorará sus almas!", frFR = "Je jetterai vos âmes en pâture à Hakkar lui-même !", ptBR = "Vou entregar suas almas para Hakkar em pessoa!", ruRU = "Я скормлю ваши души Хаккару!" },
	[11502] = { enUS = "BY FIRE BE PURGED!", deDE = "DAS FEUER WIRD EUCH LÄUTERN!", esES = "¡EL FUEGO TE PURGARÁ!", esMX = "¡QUE EL FUEGO TE PURIFIQUE!", frFR = "PAR LE FEU, SOYEZ PURIFIÉS !", ptBR = "Sejam purificados pelo fogo!", ruRU = "ОЧИСТИСЬ ЖЕ ОГНЕМ!" },
	[11583] = { enUS = "BURN! You wretches! BURN!", deDE = "BRENNT! Ihr Elenden! BRENNT!", esES = "¡QUEMAD! ¡Malditos! ¡QUEMAD!", esMX = "¡ARDAN! ¡Miserables! ¡ARDAN!", frFR = "BRÛLEZ, misérables ! BRÛLEZ !", ptBR = "QUEIMEM, seus miseráveis! QUEIMEM!", ruRU = "Горите, мерзавцы, ГОРИТЕ!" },
	[12018] = { enUS = "Reckless mortals! None may challenge the Sons of the Living flame!", deDE = "Schwächliche Sterbliche! Niemand fordert die Söhne der Lebenden Flamme heraus!", esES = "¡Imprudentes mortales! ¡Nadie puede desafiar a los Hijos de la Llama viviente!", esMX = "¡Imprudentes mortales! ¡Nadie puede desafiar a los Hijos de la Llama viviente!", frFR = "Imprudents mortels ! Nul ne défie les Fils de la Flamme vivante !", ptBR = "Mortais atrevidos. Ninguém pode desafiar os Filhos da Chama Viva!", ruRU = "Дерзкие смертные! Никто не смеет бросать вызов сынам Живого жара!" },
	[12397] = { enUS = "All mortals will perish!" },
	[13020] = { enUS = "FLAME! DEATH! DESTRUCTION! Cower, mortals before the wrath of Lord...NO - I MUST fight this! Alexstrasza help me, I MUST fight it! ", deDE = "FLAMMEN! TOD! ZERSTÖRUNG! Kniet nieder, Sterbliche, oder der Zorn von Lord... NEIN - ICH MUSS es bekämpfen! Alexstrasza, hilf mir! ICH MUSS es bekämpfen!", esES = "¡LLAMAS! ¡MUERTE! ¡DESTRUCCIÓN! Mortales, temblad ante la ira del Señor... ¡NO, DEBO luchar contra esto! ¡Que Alexstrasza me ayude, DEBO luchar contra esto!", esMX = "¡FUEGO! ¡MUERTE! ¡DESTRUCCIÓN! Póstrense mortales ante la ira del Señor... ¡NO, TENGO que combatirlo! ¡Alexstrasza ayúdame, tengo que combatirlo!", frFR = "FLAMMES ! MORT ! DESTRUCTION ! Tremblez, mortels, devant la colère du seigneur… NON ! JE DOIS lutter ! Qu'Alexstrasza me vienne en aide, JE DOIS me battre !", ptBR = "CHAMAS! MORTE! DESTRUIÇÃO! Mortais, curvem-se diante da ira do Lorde... NÃO! Eu tenho que RESISTIR! Alexstrasza, ajude-me, eu TENHO que resistir!", ruRU = "ОГОНЬ! СМЕРТЬ! РАЗРУШЕНИЕ! Трепещите, смертные, перед гневом Владыки… Нет, я должен сражаться! Алекстраза, помоги, я ДОЛЖЕН сражаться!" },
	[14834] = { enUS = "PRIDE HERALDS THE END OF YOUR WORLD.  COME, MORTALS!  FACE THE WRATH OF THE SOULFLAYER!", deDE = "EURE ÜBERHEBLICHKEIT KÜNDET BEREITS VOM ENDE DIESER WELT! KOMMT STERBLICHE - STELLT EUCH DEM ZORN DES SEELENSCHINDERS!", esES = "EL ORGULLO PRESAGIA EL FIN DE VUESTRO MUNDO. ¡VENID, MORTALES! ¡ENFRENTAOS A LA IRA DEL CAZADOR DE ALMAS!", esMX = "EL ORGULLO ANUNCIA EL FINAL DE SU MUNDO. ¡VENGAN MORTALES! ¡ENFRENTENSE A LA IRA DEL CAZADOR DE ALMAS!", frFR = "L’ORGUEIL ANNONCE LA FIN DE VOTRE MONDE. AVANCEZ, MORTELS ! AFFRONTEZ LA COLÈRE DE L’ÉCORCHEUR D’ÂMES !", ptBR = "O ORGULHO ANUNCIA O FIM DO SEU MUNDO. VENHAM, MORTAIS! ENFRENTEM A IRA DO ESFOLADOR DE ALMAS!", ruRU = "ГОРДОСТЬ ПРЕДВЕЩАЕТ ГИБЕЛЬ ВАШЕГО МИРА. ПРИДИТЕ, СМЕРТНЫЕ! ВЗГЛЯНИТЕ НА ГНЕВ СВЕЖЕВАТЕЛЯ ДУШ!" },
	[14887] = { enUS = "The strands of LIFE have been severed! The Dreamers must be avenged!", deDE = "Die Fäden des LEBENS wurden durchtrennt! Die Träumer müssen gerächt werden!", esES = "¡Los hilos de la VIDA se han roto! ¡Tenemos que vengar a los Soñadores!", esMX = "¡Los hilos de la VIDA se han roto! ¡Tenemos que vengar a los Soñadores!", frFR = "Les fils de la VIE ont été coupés ! Les Rêveurs doivent être vengés !", ptBR = "Os fios da VIDA foram cortados! Os Sonhadores serão vingados!", ruRU = "Нити ЖИЗНИ разорваны! Отомстим за Спящих!" },
	[14890] = { enUS = "Peace is but a fleeting dream! Let the NIGHTMARE reign!", deDE = "Frieden ist nur ein flüchtiger Traum! Von nun an herrscht der ALPTRAUM!", esES = "¡La paz no es más que un sueño fugaz! ¡Que reine la PESADILLA!", esMX = "¡La paz no es más que un sueño fugaz! ¡Que reine la PESADILLA!", frFR = "La paix n'est qu'un rêve éphémère ! Que le CAUCHEMAR règne !", ptBR = "A paz é um sonho efêmero! Que os PESADELOS reinem soberanos!", ruRU = "Мир - это всего лишь мимолетный сон. Пусть правит КОШМАР!" },
	[15192] = { enUS = "We must act quickly or all shall be lost!", deDE = "Wir müssen schnell handeln, oder alles ist verloren!", esES = "¡Debemos actuar con rapidez o estaremos perdidos!", esMX = "¡Debemos actuar con rapidez o estaremos perdidos!", frFR = "Nous devons agir rapidement, ou tout sera perdu !", ptBR = "Precisamos agir depressa ou tudo estará perdido!", ruRU = "Мы должны действовать быстро, иначе все пропало!" },
	[15275] = { enUS = "Your fate is sealed!", deDE = "Euer Schicksal ist besiegelt!", esES = "¡Tu destino está escrito!", esMX = "¡Tu suerte está echada!", frFR = "Votre destin est scellé !", ptBR = "Seu destino está selado!", ruRU = "Ваша судьба решена!" },
	[15276] = { enUS = "You will not escape death!", deDE = "Vor dem Tod gibt es kein Entrinnen.", esES = "¡No escaparás a la muerte!", esMX = "¡No podrán escapar de la muerte!", frFR = "Vous n’échapperez pas à la mort !", ptBR = "Vocês não escaparão da morte!", ruRU = "От смерти не уйти!" },
	[15339] = { enUS = "Sands of the desert, rise and block out the sun!", deDE = "Sande der Wüste, erhebt euch und verdunkelt die Sonne!", esES = "¡Arenas del desierto, levantaos y ocultad el sol!", esMX = "¡Que las arenas del desierto se eleven y apaguen la luz del sol!", frFR = "Sables du désert, à moi ! Cachez le soleil !", ptBR = "Areias do deserto, ergam-se e bloqueiem o sol!", ruRU = "Взвейтесь, пески пустыни, и закройте солнце!" },
	[15341] = { enUS = "Impudent fool! I will kill you myself!", deDE = "Unverschämter Narr! Ich werde Euch höchstpersönlich töten!", esES = "¡Idiota insolente! ¡Te mataré yo mismo!", esMX = "¡Loco imprudente! ¡Acabaré contigo yo mismo!", frFR = "Imbécile imprudent ! Je vais te tuer moi-même !", ptBR = "Tolo insolente! Eu mesmo vou matá-lo!", ruRU = "$gНастырный глупец:Настырная тварь;! Я сам тебя убью!" },
	[15727] = { enUS = "You will die." },
	[15928] = { enUS = "Break... you!!", deDE = "Euch... zerquetschen!", esES = "¡¡Despedazarte!!", esMX = "¡¡Yo Destrozarlos!!", frFR = "Casser… toi !", ptBR = "Matar... Vocês...!", ruRU = "Проломить… тебя!!!" },
	[15990] = { enUS = "I will freeze the blood in your veins!", deDE = "Ich werde das Blut in euren Adern gefrieren lassen!", esES = "¡Congelaré la sangre que corre por tus venas!", esMX = "¡Congelaré la sangre que corre por tus venas!", frFR = "Je vais geler le sang dans tes veines !", ptBR = "Congelarei o sangue em suas veias!", ruRU = "Я заморожу кровь в ваших венах!" },
	[16062] = { enUS = "None shall pass!", deDE = "Ihr kommt nicht vorbei!", esES = "¡Nadie pasará!", esMX = "¡Nadie pasará!", frFR = "On ne passe pas !", ptBR = "Ninguém passará!", ruRU = "Никто не пройдет!" },
}
